-- Expand Experience Pubs with real OpenStreetMap Cork pub data.
-- Source: OpenStreetMap Overpass API on 2026-06-24, bbox around Cork City and immediate suburbs, amenity=pub only.
-- Applied to FreeTrust Supabase project ref: tioqakxnqjxyuzgnwhrb only.
-- Do not apply to Sales AI One project ref: smttyfjcleqnxexfjgkx.

ALTER TABLE pubs ADD COLUMN IF NOT EXISTS data_source text;
ALTER TABLE pubs ADD COLUMN IF NOT EXISTS osm_type text;
ALTER TABLE pubs ADD COLUMN IF NOT EXISTS osm_id bigint;
ALTER TABLE pubs ADD COLUMN IF NOT EXISTS source_url text;
ALTER TABLE pubs ADD COLUMN IF NOT EXISTS source_updated_at timestamptz;
ALTER TABLE pubs ADD COLUMN IF NOT EXISTS tags jsonb DEFAULT '{}'::jsonb;

CREATE UNIQUE INDEX IF NOT EXISTS pubs_openstreetmap_unique_idx
  ON pubs (osm_type, osm_id)
  WHERE data_source = 'openstreetmap' AND osm_type IS NOT NULL AND osm_id IS NOT NULL;

