), matched_existing AS (
  UPDATE pubs p
  SET address = COALESCE(osm_rows.address, p.address),
      city = COALESCE(osm_rows.city, p.city, 'Cork'),
      country = COALESCE(p.country, 'IE'),
      lat = osm_rows.lat::numeric,
      lng = osm_rows.lng::numeric,
      phone = COALESCE(osm_rows.phone, p.phone),
      website = COALESCE(osm_rows.website, p.website),
      opening_hours = CASE WHEN osm_rows.opening_hours_text IS NOT NULL THEN jsonb_build_object('osm', osm_rows.opening_hours_text) ELSE p.opening_hours END,
      data_source = 'openstreetmap',
      osm_type = osm_rows.osm_type,
      osm_id = osm_rows.osm_id,
      source_url = 'https://www.openstreetmap.org/' || osm_rows.osm_type || '/' || osm_rows.osm_id,
      source_updated_at = now(),
      tags = COALESCE(p.tags, '{}'::jsonb) || osm_rows.tags,
      is_verified = COALESCE(p.is_verified, false)
  FROM osm_rows
  WHERE p.data_source IS DISTINCT FROM 'openstreetmap'
    AND lower(regexp_replace(regexp_replace(p.name, '^the\s+', '', 'i'), '[^a-zA-Z0-9]+', '', 'g')) = lower(regexp_replace(regexp_replace(osm_rows.name, '^the\s+', '', 'i'), '[^a-zA-Z0-9]+', '', 'g'))
  RETURNING p.id, osm_rows.osm_type, osm_rows.osm_id
)
INSERT INTO pubs (name, address, city, country, lat, lng, phone, website, opening_hours, is_verified, avg_rating, data_source, osm_type, osm_id, source_url, source_updated_at, tags)
SELECT name,
       address,
       COALESCE(city, 'Cork'),
       'IE',
       lat::numeric,
       lng::numeric,
       phone,
       website,
       CASE WHEN opening_hours_text IS NOT NULL THEN jsonb_build_object('osm', opening_hours_text) ELSE NULL END,
       false,
       NULL,
       'openstreetmap',
       osm_type,
       osm_id,
       'https://www.openstreetmap.org/' || osm_type || '/' || osm_id,
       now(),
       tags
FROM osm_rows
WHERE NOT EXISTS (
  SELECT 1 FROM matched_existing m WHERE m.osm_type = osm_rows.osm_type AND m.osm_id = osm_rows.osm_id
)
ON CONFLICT (osm_type, osm_id) WHERE data_source = 'openstreetmap' AND osm_type IS NOT NULL AND osm_id IS NOT NULL DO UPDATE
SET name = EXCLUDED.name,
    address = EXCLUDED.address,
    city = EXCLUDED.city,
    country = EXCLUDED.country,
    lat = EXCLUDED.lat,
    lng = EXCLUDED.lng,
    phone = EXCLUDED.phone,
    website = EXCLUDED.website,
    opening_hours = EXCLUDED.opening_hours,
    source_url = EXCLUDED.source_url,
    source_updated_at = now(),
    tags = EXCLUDED.tags;
